//! table plus `verify_constitution()` — the constitutional-diff law as
//! executable Rust: any row whose projected value drifts from the sealed
//! commitment is a `ConstitutionalDrift` refusal.

/// One row of the constants-vs-commitments diff table.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ConstantDiffRow {
    /// Commitment (constitution) that seals the constant.
    pub commitment: &'static str,
    /// Constant identifier (join key between seal and projection).
    pub constant: &'static str,
    /// Value sealed in the commitment.
    pub sealed: &'static str,
    /// Value the projection manufactures.
    pub projected: &'static str,
    /// "MATCH" or "DRIFT".
    pub status: &'static str,
    /// SHA-256("NAME=value") at seal time — tamper-evident fingerprint.
    pub sealed_digest: &'static str,
    /// Commitment subject (what surface the seal governs).
    pub subject: &'static str,
}

/// Typed refusal: the projection disagreed with the constitution.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ConstitutionalDrift {
    pub commitment: String,
    pub constant: String,
    pub sealed: String,
    pub projected: String,
}

impl std::fmt::Display for ConstitutionalDrift {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "constitutional_drift: {} sealed in commitment {} as {} but projection manufactures {}",
            self.constant, self.commitment, self.sealed, self.projected
        )
    }
}
impl std::error::Error for ConstitutionalDrift {}

