/// Constitutional-diff law, executable: OK(()) iff every row matches its
/// sealed commitment; otherwise the FIRST drift, citing the commitment.
pub fn verify_constitution() -> Result<(), ConstitutionalDrift> {
    for row in DIFF_TABLE {
        if row.status != "MATCH" {
            return Err(ConstitutionalDrift {
                commitment: row.commitment.to_string(),
                constant: row.constant.to_string(),
                sealed: row.sealed.to_string(),
                projected: row.projected.to_string(),
            });
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The law holds on the sealed graph: projection agrees with the
    /// constitution, zero drift rows.
    #[test]
    fn constitution_holds() {
        assert_eq!(DIFF_TABLE.len(), 17, "seventeen sealed constants expected");
        assert!(DIFF_TABLE.iter().all(|r| r.status == "MATCH"));
        assert_eq!(verify_constitution(), Ok(()));
    }

    /// Seal integrity: each row's sealed_digest re-derives as the
    /// SHA-256 of "NAME=value" using the module's own SHA-256.
    #[test]
    fn seal_digests_rederive() {
        // FIPS 180-4 SHA-256, provenance-copied pattern from the strata
        // family (self-contained, zero-crate).
        sha256_self_test();
        for row in DIFF_TABLE {
            let preimage = format!("{}={}", row.constant, row.sealed);
            let d = sha256_hex(preimage.as_bytes());
            assert_eq!(d, row.sealed_digest.to_lowercase(), "digest mismatch for {}", row.constant);
        }
    }

    /// FALSIFIER (documented in the pack README): an out-of-constitution
    /// edit — the projection manufacturing a drifted value — must be
    /// REFUSED with a drift citing the commitment.
    #[test]
    fn out_of_constitution_edit_refused() {
        let idx = DIFF_TABLE
            .iter()
            .position(|r| r.constant == "INITIAL_DIFFICULTY_TARGET")
            .expect("INITIAL_DIFFICULTY_TARGET must be in the sealed table");
        let drifted = ConstantDiffRow {
            projected: "13", // mutation of INITIAL_DIFFICULTY_TARGET (sealed 12)
            status: "DRIFT",
            ..DIFF_TABLE[idx].clone()
        };
        let result = verify_row(&drifted);
        let err = result.expect_err("drifted row must be refused");
        assert_eq!(err.commitment, "GenesisLayout", "violation must cite the commitment");
        assert_eq!(err.constant, "INITIAL_DIFFICULTY_TARGET");
        assert_eq!(err.sealed, "12");
        assert_eq!(err.projected, "13");
    }

    /// DRIFT NEGATIVE on a NEW surface (L166): mutating a sealed LAW —
    /// the MEMPOOL_LEDGER_ADMISSION composition law downgraded from
    /// NECESSARY_NOT_SUFFICIENT to a bare-sufficient claim — must be
    /// REFUSED with a drift citing the MempoolLedgerAdmission commitment.
    #[test]
    fn law_surface_drift_refused() {
        let idx = DIFF_TABLE
            .iter()
            .position(|r| r.constant == "MEMPOOL_LEDGER_ADMISSION")
            .expect("MEMPOOL_LEDGER_ADMISSION must be in the sealed table");
        assert_eq!(DIFF_TABLE[idx].sealed, "NECESSARY_NOT_SUFFICIENT");
        let drifted = ConstantDiffRow {
            projected: "SUFFICIENT", // mutation: law downgraded to sufficient
            status: "DRIFT",
            ..DIFF_TABLE[idx].clone()
        };
        let err = verify_row(&drifted).expect_err("law-surface drift must be refused");
        assert_eq!(
            err.commitment, "MempoolLedgerAdmission",
            "violation must cite the law commitment"
        );
        assert_eq!(err.constant, "MEMPOOL_LEDGER_ADMISSION");
        assert_eq!(err.sealed, "NECESSARY_NOT_SUFFICIENT");
        assert_eq!(err.projected, "SUFFICIENT");
    }

    /// DRIFT NEGATIVE on the NEWEST surface (L192): mutating the sealed
    /// A2A wire law — projecting a DIFFERENT wire code for
    /// A2A_WIRE_CODE (-32000 -> -32001, outside the designated server-error
    /// range code) — must be REFUSED with a drift citing the A2aWireLaw
    /// commitment.
    #[test]
    fn a2a_wire_law_drift_refused() {
        let idx = DIFF_TABLE
            .iter()
            .position(|r| r.constant == "A2A_WIRE_CODE")
            .expect("A2A_WIRE_CODE must be in the sealed table");
        assert_eq!(DIFF_TABLE[idx].sealed, "-32000");
        let drifted = ConstantDiffRow {
            projected: "-32001", // mutation: a different wire code
            status: "DRIFT",
            ..DIFF_TABLE[idx].clone()
        };
        let err = verify_row(&drifted).expect_err("A2A wire-code drift must be refused");
        assert_eq!(
            err.commitment, "A2aWireLaw",
            "violation must cite the law commitment"
        );
        assert_eq!(err.constant, "A2A_WIRE_CODE");
        assert_eq!(err.sealed, "-32000");
        assert_eq!(err.projected, "-32001");
    }

    fn verify_row(row: &ConstantDiffRow) -> Result<(), ConstitutionalDrift> {
        if row.status != "MATCH" {
            Err(ConstitutionalDrift {
                commitment: row.commitment.to_string(),
                constant: row.constant.to_string(),
                sealed: row.sealed.to_string(),
                projected: row.projected.to_string(),
            })
        } else {
            Ok(())
        }
    }

    /// SABOTAGE TWIN (L124) — unframed seal digest: SHA-256 over the
    /// non-canonical concatenation `sealed || constant` (wrong order, no
    /// `NAME=` framing). The seal-rederive court pins the canonical
    /// preimage `"NAME=value"`; this twin never reproduces it.
    fn twin_unframed_seal_digest(constant: &str, sealed: &str) -> String {
        sha256_hex(format!("{}{}", sealed, constant).as_bytes())
    }

    /// Court (sabotage twin, L124): the twin digest differs from every
    /// sealed digest — the seal-rederive law catches it on ALL rows, and
    /// on the honest rows the canonical re-derivation still matches.
    #[test]
    fn sabotage_twin_unframed_seal_digest_is_caught() {
        for row in DIFF_TABLE {
            let canonical = format!("{}={}", row.constant, row.sealed);
            assert_eq!(
                sha256_hex(canonical.as_bytes()),
                row.sealed_digest.to_lowercase(),
                "canonical seal digest must re-derive for {}",
                row.constant
            );
            assert_ne!(
                twin_unframed_seal_digest(row.constant, row.sealed),
                row.sealed_digest.to_lowercase(),
                "unframed twin digest collided with the sealed digest for {} — twin not caught",
                row.constant
            );
        }
    }

    // ── Minimal SHA-256 (FIPS 180-4) for the digest re-derivation ──

    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ];

    pub fn sha256(data: &[u8]) -> [u8; 32] {
        let mut h: [u32; 8] = [
            0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
            0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
        ];
        let bitlen = (data.len() as u64).wrapping_mul(8);
        let mut msg = data.to_vec();
        msg.push(0x80);
        while msg.len() % 64 != 56 {
            msg.push(0);
        }
        msg.extend_from_slice(&bitlen.to_be_bytes());
        for chunk in msg.chunks_exact(64) {
            let mut w = [0u32; 64];
            for i in 0..16 {
                w[i] = u32::from_be_bytes([chunk[4 * i], chunk[4 * i + 1], chunk[4 * i + 2], chunk[4 * i + 3]]);
            }
            for i in 16..64 {
                let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
                let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
                w[i] = w[i - 16]
                    .wrapping_add(s0)
                    .wrapping_add(w[i - 7])
                    .wrapping_add(s1);
            }
            let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
                (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
            for i in 0..64 {
                let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
                let ch = (e & f) ^ ((!e) & g);
                let t1 = hh
                    .wrapping_add(s1)
                    .wrapping_add(ch)
                    .wrapping_add(K[i])
                    .wrapping_add(w[i]);
                let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
                let maj = (a & b) ^ (a & c) ^ (b & c);
                let t2 = s0.wrapping_add(maj);
                hh = g;
                g = f;
                f = e;
                e = d.wrapping_add(t1);
                d = c;
                c = b;
                b = a;
                a = t1.wrapping_add(t2);
            }
            h[0] = h[0].wrapping_add(a);
            h[1] = h[1].wrapping_add(b);
            h[2] = h[2].wrapping_add(c);
            h[3] = h[3].wrapping_add(d);
            h[4] = h[4].wrapping_add(e);
            h[5] = h[5].wrapping_add(f);
            h[6] = h[6].wrapping_add(g);
            h[7] = h[7].wrapping_add(hh);
        }
        let mut out = [0u8; 32];
        for (i, v) in h.iter().enumerate() {
            out[4 * i..4 * i + 4].copy_from_slice(&v.to_be_bytes());
        }
        out
    }

    pub fn sha256_hex(data: &[u8]) -> String {
        sha256(data).iter().map(|b| format!("{:02x}", b)).collect()
    }

    fn sha256_self_test() {
        assert_eq!(sha256_hex(b""), "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
        assert_eq!(sha256_hex(b"abc"), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
    }
}
